package com.kareem.lifeos;

import android.app.Activity;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.os.Bundle;
import android.speech.RecognizerIntent;
import android.text.Editable;
import android.text.TextWatcher;
import android.view.Gravity;
import android.view.View;
import android.view.inputmethod.EditorInfo;
import android.widget.Button;
import android.widget.EditText;
import android.widget.HorizontalScrollView;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Search = capability discovery + typed federation over real providers only. */
public final class SearchActivity extends Activity {
    private static final int VOICE=41;private LinearLayout content;private EditText query;private String filter="All";private final Map<String,Button> chipViews=new LinkedHashMap<>();
    @Override public void onCreate(Bundle s){super.onCreate(s);render();String initial=getIntent().getStringExtra("initial_query");String initialFilter=getIntent().getStringExtra("initial_filter");if(initialFilter!=null&&!initialFilter.isEmpty()){filter=initialFilter;updateChips();}if(initial!=null&&!initial.trim().isEmpty()){query.setText(initial.trim());query.setSelection(query.length());}}
    @Override protected void onResume(){super.onResume();if(query!=null&&query.getText().toString().trim().isEmpty())showLanding();}

    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(LifeOsUi.BG);root.addView(LifeOsUi.topBar(this,"Search",false));
        LinearLayout search=new LinearLayout(this);search.setGravity(Gravity.CENTER_VERTICAL);search.setPadding(LifeOsUi.dp(this,13),0,LifeOsUi.dp(this,5),0);search.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE_2,LifeOsUi.BORDER,25));search.addView(LifeOsUi.icon(this,LifeOsIconView.SEARCH,LifeOsUi.MUTED,20),new LinearLayout.LayoutParams(LifeOsUi.dp(this,24),LifeOsUi.dp(this,24)));
        query=new EditText(this);query.setHint("Search your LifeOS…");query.setHintTextColor(LifeOsUi.MUTED);query.setTextColor(LifeOsUi.TEXT);query.setSingleLine(true);query.setTextSize(LifeOsUi.refSp(12.2f));LifeOsUi.weight(query,500);query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);query.setPadding(LifeOsUi.dp(this,9),0,0,0);query.setBackgroundColor(Color.TRANSPARENT);search.addView(query,new LinearLayout.LayoutParams(0,-1,1));View mic=LifeOsUi.iconTouch(this,LifeOsIconView.MIC,LifeOsUi.MUTED,20,40);mic.setContentDescription("Voice search");mic.setOnClickListener(v->startVoice());search.addView(mic,new LinearLayout.LayoutParams(LifeOsUi.dp(this,40),LifeOsUi.dp(this,40)));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,50));qp.setMargins(LifeOsUi.dp(this,16),0,LifeOsUi.dp(this,16),LifeOsUi.dp(this,9));root.addView(search,qp);
        HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);chips.setPadding(LifeOsUi.dp(this,16),0,LifeOsUi.dp(this,8),LifeOsUi.dp(this,7));addChip(chips,"All","All");for(FunctionalCapabilityRegistry.Capability c:FunctionalCapabilityRegistry.all(this))addChip(chips,c.id,c.label);hs.addView(chips);root.addView(hs);
        ScrollView sc=new ScrollView(this);sc.setVerticalScrollBarEnabled(false);sc.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(LifeOsUi.dp(this,16),0,LifeOsUi.dp(this,16),LifeOsUi.dp(this,10));sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));root.addView(LifeOsUi.bottomNav(this,SearchActivity.class));setContentView(root);
        query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){runSearch();}public void afterTextChanged(Editable e){}});query.setOnEditorActionListener((v,id,e)->{if(id==EditorInfo.IME_ACTION_SEARCH){saveHistory(query.getText().toString());runSearch();return true;}return false;});showLanding();
    }
    private void addChip(LinearLayout chips,String id,String label){Button b=LifeOsUi.chip(this,label,id.equals(filter));b.setOnClickListener(v->{filter=id;updateChips();runSearch();});chipViews.put(id,b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,LifeOsUi.dp(this,34));p.setMargins(0,0,LifeOsUi.dp(this,7),0);chips.addView(b,p);}
    private void updateChips(){for(Map.Entry<String,Button> e:chipViews.entrySet()){boolean on=e.getKey().equals(filter);e.getValue().setBackground(LifeOsUi.round(this,on?LifeOsUi.BLUE:LifeOsUi.SURFACE_2,on?LifeOsUi.BLUE:LifeOsUi.BORDER,18));e.getValue().setTextColor(on?Color.WHITE:LifeOsUi.TEXT);}}

    private void showLanding(){if(content==null)return;content.removeAllViews();content.addView(LifeOsUi.section(this,"Connected capabilities"));List<FunctionalCapabilityRegistry.Capability> caps=FunctionalCapabilityRegistry.all(this);LinearLayout grid=new LinearLayout(this);grid.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<caps.size();i+=2){LinearLayout row=new LinearLayout(this);FunctionalCapabilityRegistry.Capability left=caps.get(i);row.addView(capabilityTile(left),new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,82),1));if(i+1<caps.size()){LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,82),1);rp.setMargins(LifeOsUi.dp(this,7),0,0,0);row.addView(capabilityTile(caps.get(i+1)),rp);}else row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));LinearLayout.LayoutParams rowp=new LinearLayout.LayoutParams(-1,-2);rowp.setMargins(0,0,0,LifeOsUi.dp(this,7));grid.addView(row,rowp);}content.addView(grid);
        TextView truth=LifeOsUi.text(this,"Only capabilities backed by a real source are shown here. Files, Places and Projects will return only after their real providers exist.",9.7f,LifeOsUi.MUTED);LifeOsUi.weight(truth,500);truth.setPadding(LifeOsUi.dp(this,2),LifeOsUi.dp(this,5),LifeOsUi.dp(this,2),LifeOsUi.dp(this,7));content.addView(truth);
        List<String> history=history();if(!history.isEmpty()){LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView h=LifeOsUi.section(this,"Recent searches");head.addView(h,new LinearLayout.LayoutParams(0,-2,1));TextView clear=LifeOsUi.text(this,"Clear",10.5f,LifeOsUi.BLUE);LifeOsUi.weight(clear,500);clear.setOnClickListener(v->{prefs().edit().remove("history").apply();showLanding();});head.addView(clear);content.addView(head);for(String s:history)recentRow(s,()->{query.setText(s);query.setSelection(query.length());});}
    }

    private View capabilityTile(FunctionalCapabilityRegistry.Capability c){LinearLayout tile=new LinearLayout(this);tile.setOrientation(LinearLayout.HORIZONTAL);tile.setGravity(Gravity.CENTER_VERTICAL);tile.setPadding(LifeOsUi.dp(this,10),LifeOsUi.dp(this,8),LifeOsUi.dp(this,9),LifeOsUi.dp(this,8));tile.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE,LifeOsUi.BORDER,13));tile.addView(LifeOsUi.iconTile(this,c.icon,c.color,34),new LinearLayout.LayoutParams(LifeOsUi.dp(this,34),LifeOsUi.dp(this,34)));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(LifeOsUi.dp(this,9),0,0,0);tile.addView(copy,cp);TextView title=LifeOsUi.text(this,c.label,11.4f,LifeOsUi.TEXT);LifeOsUi.weight(title,700);copy.addView(title);TextView count=LifeOsUi.text(this,c.countLine(),9.6f,LifeOsUi.MUTED);LifeOsUi.weight(count,500);count.setPadding(0,LifeOsUi.dp(this,2),0,0);copy.addView(count);TextView secondary=LifeOsUi.text(this,c.status,8.8f,c.availability==FunctionalCapabilityRegistry.Availability.OPERATIONAL?c.color:LifeOsUi.AMBER);LifeOsUi.weight(secondary,500);secondary.setMaxLines(1);copy.addView(secondary);tile.setOnClickListener(v->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability",c.id)));return tile;}
    private void recentRow(String title,Runnable action){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,LifeOsUi.dp(this,2),0,LifeOsUi.dp(this,2));row.addView(LifeOsUi.icon(this,LifeOsIconView.HISTORY,LifeOsUi.MUTED,20),new LinearLayout.LayoutParams(LifeOsUi.dp(this,28),LifeOsUi.dp(this,38)));TextView t=LifeOsUi.text(this,title,11.8f,LifeOsUi.TEXT);LifeOsUi.weight(t,500);t.setPadding(LifeOsUi.dp(this,9),0,0,0);row.addView(t,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,44),1));row.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TERTIARY,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,22)));row.setOnClickListener(v->action.run());content.addView(row);}

    private void runSearch(){String q=query.getText().toString().trim();if(q.isEmpty()){showLanding();return;}content.removeAllViews();List<FunctionalCapabilityRegistry.ObjectItem> xs=FunctionalSearchEngine.search(this,q,filter,60);if(xs.isEmpty()){TextView none=LifeOsUi.text(this,"No matching object exists in the connected LifeOS providers.",11.5f,LifeOsUi.MUTED);LifeOsUi.weight(none,500);none.setPadding(0,LifeOsUi.dp(this,14),0,0);content.addView(none);return;}for(FunctionalCapabilityRegistry.ObjectItem r:xs)resultRow(r);}
    private void resultRow(FunctionalCapabilityRegistry.ObjectItem r){FunctionalCapabilityRegistry.Capability cap=FunctionalCapabilityRegistry.find(this,r.capabilityId);if(cap==null)return;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,LifeOsUi.dp(this,7),0,LifeOsUi.dp(this,7));row.addView(LifeOsUi.iconTile(this,cap.icon,cap.color,36),new LinearLayout.LayoutParams(LifeOsUi.dp(this,36),LifeOsUi.dp(this,36)));LinearLayout txt=new LinearLayout(this);txt.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(LifeOsUi.dp(this,10),0,LifeOsUi.dp(this,8),0);row.addView(txt,tp);TextView t=LifeOsUi.text(this,r.title,12.2f,LifeOsUi.TEXT);LifeOsUi.weight(t,600);t.setMaxLines(1);txt.addView(t);TextView s=LifeOsUi.text(this,r.summary,10.2f,LifeOsUi.MUTED);LifeOsUi.weight(s,500);s.setPadding(0,LifeOsUi.dp(this,2),0,0);s.setMaxLines(2);txt.addView(s);TextView m=LifeOsUi.text(this,cap.label+(r.meta.isEmpty()?"":" · "+r.meta),9f,cap.color);LifeOsUi.weight(m,500);m.setMaxLines(1);txt.addView(m);row.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TERTIARY,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,22)));row.setOnClickListener(v->openResult(r));content.addView(row);}
    private void openResult(FunctionalCapabilityRegistry.ObjectItem r){saveHistory(query.getText().toString());if("conversations".equals(r.capabilityId)){startActivity(new Intent(this,ConversationDetailActivity.class).putExtra("conversation_id",r.objectId));return;}startActivity(new Intent(this,FunctionalObjectDetailActivity.class).putExtra("capability_id",r.capabilityId).putExtra("object_id",r.objectId));}

    private void saveHistory(String value){String s=value==null?"":value.trim();if(s.isEmpty())return;ArrayList<String> h=new ArrayList<>(history());h.remove(s);h.add(0,s);while(h.size()>5)h.remove(h.size()-1);prefs().edit().putString("history",android.text.TextUtils.join("\u001f",h)).apply();}
    private List<String> history(){String raw=prefs().getString("history","");if(raw==null||raw.isEmpty())return new ArrayList<>();return new ArrayList<>(Arrays.asList(raw.split("\u001f")));}
    private SharedPreferences prefs(){return getSharedPreferences("lifeos_search",MODE_PRIVATE);}
    private void startVoice(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);startActivityForResult(i,VOICE);}catch(Throwable ignored){}}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==VOICE&&resultCode==RESULT_OK&&data!=null){ArrayList<String> xs=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(xs!=null&&!xs.isEmpty()){query.setText(xs.get(0));query.setSelection(query.length());}}}
}
